[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$PacketPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path;if([IO.Path]::IsPathRooted($PacketPath)){throw 'PacketPath must be project-relative.'}
$rel=$PacketPath.Replace('\','/').Trim();if($rel.Contains('..')-or $rel -notmatch '^ES/Output/.+\.json$'){throw 'PacketPath must remain under ES/Output.'};$full=Join-Path $root ($rel.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path -LiteralPath $full -PathType Leaf)){throw "Review packet missing: $rel"}
$p=([Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes($full))|ConvertFrom-Json);foreach($f in @('schemaVersion','intent','conclusion','findings','evidenceGaps')){if([string]::IsNullOrWhiteSpace([string]$p.$f)-and @($p.$f).Count -eq 0){throw "Review packet missing ${f}."}};if([string]$p.schemaVersion -ne '1'-or [string]$p.conclusion -notin @('pass','conditional','fail')){throw 'Review packet schema or conclusion is invalid.'};foreach($f in @($p.findings)){if([string]::IsNullOrWhiteSpace([string]$f.severity)-or [string]::IsNullOrWhiteSpace([string]$f.scenario)-or [string]::IsNullOrWhiteSpace([string]$f.correction)){throw 'Finding requires severity, scenario and correction.'}}
Write-Output "PASS: adversarial review packet preserves findings and evidence gaps: $rel"
